// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId     the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger      'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter the launch row's Client link (one record id) to scope the run to one client; '' = all clients
// sd.launch.full         true on Mondays (Asia/Jerusalem) and on every launched run: every flag is read and every
//                        client gets the full report. False on the other days: only the daily flags, and only
//                        emergencies are posted (standards/infrastructure.md, The daily and weekly read)
// sd.launch.live         LIVE_CORRECTIONS below. False = the corrections are planned and reported as "would
//                        change", never applied. Flipped to true by a push once the Operator approved a dry report.
const LIVE_CORRECTIONS = false;

const sd = $getWorkflowStaticData('global');
let launch = null;
try { const r = $('Fetch Launch Record').first().json; if (r && r.id) launch = r; } catch (e) {}
const f = (launch && launch.fields) || launch || {};
const cl = Array.isArray(f.Client) && f.Client.length ? f.Client[0] : '';
const clientFilter = (cl && typeof cl === 'object') ? String(cl.id || '') : String(cl || '');
const full = !!launch || $now.setZone('Asia/Jerusalem').weekday === 1;
sd.launch = { recordId: launch ? String(launch.id) : '', trigger: launch ? 'form' : 'schedule', clientFilter, startedAt: $now.toMillis(), full, live: LIVE_CORRECTIONS };
sd.results = [];
delete sd.cw;
return [{ json: Object.assign({}, sd.launch) }];

// Every client with a sender workspace, the Flowroots pool last so its block closes the report.
const sd = $getWorkflowStaticData('global');
sd.results = [];
const launch = sd.launch || {};
const cf = String(launch.clientFilter || '');
const all = $('Get PV Clients').all().filter(it => it.json && it.json.id);
const picked = cf ? all.filter(it => it.json.id === cf) : all;
sd.scope = cf ? (picked.length ? 'one client (on demand)' : 'client filter matched no client with a sender workspace') : 'all clients';
// A loop node that receives nothing never runs, so an empty pick still has to reach the close.
if (!picked.length) return [{ json: { _empty: true } }];
const rows = picked.map(it => {
  const j = it.json; const f = j.fields || j;
  const name = String(f['Client'] || '');
  return {
    clientRecId: j.id,
    clientName: name,
    isPool: name.toLowerCase() === 'flowroots',
    pvWorkspace: String(f['PlusVibe Workspace ID'] || '').trim(),
    clientChannel: String(f['Slack Channel ID'] || '').trim(),
    clientReports: f['Infra Reports to Client'] === true,
  };
}).filter(r => r.pvWorkspace);
if (!rows.length) return [{ json: { _empty: true } }];
rows.sort((a, b) => (a.isPool === b.isPool ? a.clientName.localeCompare(b.clientName) : (a.isPool ? 1 : -1)));
return rows.map(r => ({ json: r }));

// A fresh scratch space for this client. The nodes that only run on some days or some clients (the
// corrections, the read-back, the stats) write into sd.cw; Decide reads only sd.cw for them. So a node
// that did not run for this client can never hand Decide the previous client's data, which a plain
// node reference inside a loop would. Record Outcome deletes it before the next client.
const sd = $getWorkflowStaticData('global');
const cw = $('Loop Over Clients').first().json;
sd.cw = { client: String(cw.clientName || ''), plan: null, fixes: null, readback: null, stats: null };
return $input.all();

